def ex_table(mid, cols=None, maxrows=None, use='pw'):
    m = MODELS[mid]
    rows = m[use]
    names = [p[0] for p in m['params']]
    cols = cols or names
    out = ['    Examples:', '      | ' + ' | '.join(cols) + ' | expected | reason |']
    for r in rows[:maxrows] if maxrows else rows:
        exp = r['_exp']
        out.append('      | ' + ' | '.join(str(r[c]) for c in cols) + f' | {exp[0]} | {exp[1]} |')
    return out

