def gherkin(s):
    out = ['```gherkin', f'Feature: {s["title"]}', '  Background:', '    Given the investment product is active for tenant "Owner Portfolio" and the virtual clock is 2027-05-04T10:00:00+05:30', '    And Tier 2 models are disabled for investor data (DEC-808)']
    num = s['id'].split('-')[1] + s['id'].split('-')[2][2:]
    k = 0
    for tag, title, lines in s['scen']:
        k += 1
        out.append('')
        out.append(f'  {tag}')
        out.append(f'  Scenario: AC-{num}-{k:02d} {title}')
        for ln in lines:
            out.append('    ' + ln)
    k += 1
    out += ['', '  @perm @sec @BRL-TEN-04', f'  Scenario: AC-{num}-{k:02d} Permission – other issuer\'s object is invisible',
            '    When a user scoped to startup "AppNAI" requests an object of startup "MedMaarg" or of tenant "External-A"', '    Then the response is a uniform 404 and no row, outbox event, provider call or notification is produced']
    k += 1
    out += ['', '  @obs', f'  Scenario: AC-{num}-{k:02d} Observability – decision audited',
            '    When any decision in this story is made', '    Then an audit event carries correlation_id, actor, rule or control id, pack versions and outcome']
    if s['outline']:
        mid, cols, mx = s['outline']
        m = MODELS[mid]
        k += 1
        names = cols or [p[0] for p in m['params']]
        out += ['', f'  @DM-{mid}', f'  Scenario Outline: AC-{num}-{k:02d} {m["title"]} – generated combinations ({mid}, {"pairwise" if m["t"] != "all" else "exhaustive"})',
                '    Given the parameter values ' + ', '.join(f'<{c}>' for c in names), '    When the decision is evaluated', '    Then the outcome is <expected> with reason <reason>', '    And a non-allow outcome produces no external side effect']
        rows = m['pw']
        if cols:
            seen = set(); rr = []
            for r in m['rows'] + m['base']:
                key = tuple(r[c] for c in cols)
                if key not in seen:
                    seen.add(key); rr.append(r)
            rows = rr[:mx] if mx else rr
        out.append('    Examples:')
        out.append('      | ' + ' | '.join(names) + ' | expected | reason |')
        for r in rows:
            out.append('      | ' + ' | '.join(str(r[c]) for c in names) + f' | {r["_exp"][0]} | {r["_exp"][1]} |')
    out.append('```')
    return out

